499	// AcceptInvite accepts the invite with this token: it finds or creates the user for the invited address (named name),
500	// makes them a member with the invite's role and gives them a first API key.
501	func (s *Store) AcceptInvite(token, name string, now time.Time) (User, Member, APIKey, error) {
502		s.mu.Lock()
503		defer s.mu.Unlock()
504		var inv Invite
505		found := false
506		for _, i := range s.invites {
507			if i.Token == token && token != "" {
508				inv, found = i, true
509				break
510			}
511		}
512		if !found || inv.RevokedAt != nil {
513			return User{}, Member{}, APIKey{}, ErrNotFound
514		}
515		var u User
516		if id, ok := s.usersByEmail[normEmail(inv.Email)]; ok {
517			u = s.users[id]
518		} else {
519			name = strings.TrimSpace(name)
520			if name == "" {
521				return User{}, Member{}, APIKey{}, invalid("a new user needs a name")
522			}
523			u = User{ID: s.newID("usr"), Email: inv.Email, Name: name, CreatedAt: now.UTC()}
524			s.users[u.ID] = u
525			s.usersByEmail[normEmail(u.Email)] = u.ID
526		}
527		m, err := s.addMember(inv.OrgID, u.ID, inv.Role, now)
528		if err != nil {
529			return User{}, Member{}, APIKey{}, err
530		}
531		k, err := s.createAPIKey(inv.OrgID, u.ID, "Default", now)
532		if err != nil {
533			return User{}, Member{}, APIKey{}, err
534		}
535		t := now.UTC()
536		inv.AcceptedAt = &t
537		s.invites[inv.ID] = inv
538		return u, m, k, nil
539	}
